// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetComprovanteUrl Gera uma URL assinada para baixar o comprovante (delegado inteiramente a platform/documents).
	// (GET /api/v1/financeiro/comprovantes/{documentId}/url)
	GetComprovanteUrl(ctx context.Context, request GetComprovanteUrlRequestObject) (GetComprovanteUrlResponseObject, error)
	// ListContas Lista todas as contas contábeis (sem paginação, FIN-D-021).
	// (GET /api/v1/financeiro/contas)
	ListContas(ctx context.Context, request ListContasRequestObject) (ListContasResponseObject, error)
	// CreateConta Cria uma conta contábil, raiz ou subconta.
	// (POST /api/v1/financeiro/contas)
	CreateConta(ctx context.Context, request CreateContaRequestObject) (CreateContaResponseObject, error)
	// RenameConta Renomeia uma conta, só enquanto nunca tiver sido usada em um lançamento.
	// (PATCH /api/v1/financeiro/contas/{id})
	RenameConta(ctx context.Context, request RenameContaRequestObject) (RenameContaResponseObject, error)
	// DeactivateConta Desativa uma conta contábil (nunca excluída).
	// (POST /api/v1/financeiro/contas/{id}/deactivate)
	DeactivateConta(ctx context.Context, request DeactivateContaRequestObject) (DeactivateContaResponseObject, error)
	// ListLancamentos Lista todos os lançamentos, incluindo CANCELADA (sem paginação, FIN-D-021).
	// (GET /api/v1/financeiro/lancamentos)
	ListLancamentos(ctx context.Context, request ListLancamentosRequestObject) (ListLancamentosResponseObject, error)
	// CreateLancamento Cria um lançamento (receita ou despesa).
	// (POST /api/v1/financeiro/lancamentos)
	CreateLancamento(ctx context.Context, request CreateLancamentoRequestObject) (CreateLancamentoResponseObject, error)
	// CreateDevolucao Cria uma despesa de devolução, referenciando a receita recebida que devolve (FIN-D-003).
	// (POST /api/v1/financeiro/lancamentos/devolucoes)
	CreateDevolucao(ctx context.Context, request CreateDevolucaoRequestObject) (CreateDevolucaoResponseObject, error)
	// UpdateLancamento Substitui os campos editáveis do lançamento, só enquanto CRIADA.
	// (PUT /api/v1/financeiro/lancamentos/{id})
	UpdateLancamento(ctx context.Context, request UpdateLancamentoRequestObject) (UpdateLancamentoResponseObject, error)
	// CancelLancamento Cancela um lançamento (CRIADA, RECEBIDA ou PAGA), com motivo obrigatório.
	// (POST /api/v1/financeiro/lancamentos/{id}/cancel)
	CancelLancamento(ctx context.Context, request CancelLancamentoRequestObject) (CancelLancamentoResponseObject, error)
	// ListComprovantes Lista os comprovantes do lançamento, mais novo primeiro (sem paginação, FIN-D-021).
	// (GET /api/v1/financeiro/lancamentos/{id}/comprovantes)
	ListComprovantes(ctx context.Context, request ListComprovantesRequestObject) (ListComprovantesResponseObject, error)
	// CreateComprovante Anexa um comprovante ao lançamento (multipart/form-data, delegado inteiramente a platform/documents).
	// (POST /api/v1/financeiro/lancamentos/{id}/comprovantes)
	CreateComprovante(ctx context.Context, request CreateComprovanteRequestObject) (CreateComprovanteResponseObject, error)
	// PayLancamento Transiciona uma despesa CRIADA para PAGA.
	// (POST /api/v1/financeiro/lancamentos/{id}/pay)
	PayLancamento(ctx context.Context, request PayLancamentoRequestObject) (PayLancamentoResponseObject, error)
	// ReceiveLancamento Transiciona uma receita CRIADA para RECEBIDA.
	// (POST /api/v1/financeiro/lancamentos/{id}/receive)
	ReceiveLancamento(ctx context.Context, request ReceiveLancamentoRequestObject) (ReceiveLancamentoResponseObject, error)
	// GetSaldo Consulta o saldo atual (soma RECEBIDA menos soma PAGA por status atual).
	// (GET /api/v1/financeiro/saldo)
	GetSaldo(ctx context.Context, request GetSaldoRequestObject) (GetSaldoResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

